import django.db.models.deletion
from django.conf import settings
from django.db import migrations, models
from django.utils import timezone


def move_pdfs_to_versions(apps, schema_editor):
    """Turn each existing contract PDF into version 1 and give the contract a reference."""
    Contract = apps.get_model("documents", "Contract")
    ContractVersion = apps.get_model("documents", "ContractVersion")
    ContractSequence = apps.get_model("documents", "ContractSequence")

    for contract in Contract.objects.exclude(pdf_file="").order_by("pk"):
        generated_at = contract.generated_at or timezone.now()
        sequence, _created = ContractSequence.objects.get_or_create(
            tenant_id=contract.tenant_id, year=generated_at.year
        )
        sequence.last_number += 1
        sequence.save()
        contract.reference = f"C-{sequence.year}-{sequence.last_number:03d}"
        contract.save(update_fields=["reference"])
        version = ContractVersion.objects.create(
            tenant_id=contract.tenant_id,
            contract=contract,
            number=1,
            pdf_file=contract.pdf_file.name,
        )
        # created_at is auto_now_add: keep the original generation date.
        ContractVersion.objects.filter(pk=version.pk).update(created_at=generated_at)


